"""Generated byte-packing C agrees with the checked compact tiling plan."""

import ctypes
import shutil
import subprocess

import pytest

from merlin.compile.c_tiling import render_looped_mnk_c
from merlin.semantic_compiler.model import IndexMap, KernelRequest, SemanticNode, TensorType
from merlin.semantic_compiler.ordered_mnk_tiling import (
    LoopedMNKTiling,
    assemble_looped_mnk_outputs,
    materialize_looped_mnk_inputs,
)


@pytest.mark.parametrize(
    "shape,geometry,widths",
    [((7, 11, 9), (3, 5, 4), (2, 4)), ((64, 64, 64), (32, 32, 32), (1, 2)), ((1, 7, 65), (32, 32, 32), (1, 2))],
)
def test_generated_c_packs_and_assembles_all_valid_bytes(tmp_path, shape, geometry, widths):
    compiler = shutil.which("cc")
    if not compiler:
        pytest.skip("C compiler unavailable")
    m, n, k = shape
    tm, tn, tk = geometry
    iw, ow = widths
    maps = (
        IndexMap(3, ((1, 0, 0), (0, 0, 1)), (0, 0)),
        IndexMap(3, ((0, 1, 0), (0, 0, 1)), (0, 0)),
        IndexMap(3, ((1, 0, 0), (0, 1, 0)), (0, 0)),
    )
    request = KernelRequest(
        (
            SemanticNode("a", "input", (), TensorType((m, k), "i8", "raw-byte"), effect="input"),
            SemanticNode("w", "input", (), TensorType((n, k), "i8", "raw-byte"), effect="input"),
            SemanticNode("y", "matmul", ("a", "w"), TensorType((m, n), "i32", "ordered"), index_maps=maps),
        ),
        ("y",),
        ("external",),
        (("a", "external"), ("w", "external")),
        "synthetic",
    )
    plan = LoopedMNKTiling(
        request,
        tm,
        tn,
        tk,
        "ordered",
        iw,
        ow,
        bytes([0x35]) * iw if m % tm or n % tn else None,
        bytes([0x72]) * iw if k % tk else None,
    )
    source = (
        render_looped_mnk_c(plan, "packed")
        + f"""
void pack(uint8_t *a, uint8_t *w, const uint8_t *x, const uint8_t *y) {{
  packed_pack_rows(a,x,{m}u,{tm}u); packed_pack_rows(w,y,{n}u,{tn}u);
}}
void assemble(uint8_t *out, const uint8_t *tiles) {{ packed_assemble_output(out,tiles); }}
"""
    )
    (tmp_path / "pack.c").write_text(source)
    library_path = tmp_path / f"pack-{m}-{n}-{k}-{iw}-{ow}.so"
    subprocess.run(
        [compiler, "-std=c11", "-Wall", "-Wextra", "-Werror", "-shared", "-fPIC", "pack.c", "-o", str(library_path)],
        cwd=tmp_path,
        check=True,
        capture_output=True,
    )
    library = ctypes.CDLL(str(library_path))
    library.pack.argtypes = [ctypes.c_void_p] * 4
    library.assemble.argtypes = [ctypes.c_void_p] * 2
    a, w = bytes(i % 251 for i in range(m * k * iw)), bytes((i * 17) % 251 for i in range(n * k * iw))
    expected = materialize_looped_mnk_inputs(plan, {"a": a, "w": w})
    packed = [ctypes.create_string_buffer(size) for size in plan.buffer_bytes[:2]]
    library.pack(*packed, ctypes.create_string_buffer(a), ctypes.create_string_buffer(w))
    assert tuple(x.raw for x in packed) == expected
    tiles = bytes((i * 13) % 251 for i in range(plan.buffer_bytes[2]))
    output = ctypes.create_string_buffer(m * n * ow)
    library.assemble(output, ctypes.create_string_buffer(tiles))
    assert output.raw == assemble_looped_mnk_outputs(plan, tiles)
